# এসএসসি উচ্চতর গণিত অধ্যায় ১৪ (সম্ভাবনা): পাঠ্যবইয়ের ২টি সৃজনশীল (হুবহু, ১৭ ও ১৮ নং) + এদের মতো ১০টি
# + অনুশীলনীর অন্যান্য অংক মিশিয়ে সহজ ৮টি ও মধ্যম ৮টি (শুধু উত্তর)। সব উত্তর কোডে গণনা করে যাচাই করা
import json, os
from fractions import Fraction as F
from itertools import product
def P(space,cond): s=list(space); return F(sum(1 for w in s if cond(w)),len(s))
coin=lambda n,a='HT': list(product(a,repeat=n))
dice2=list(product(range(1,7),repeat=2))
def nr(*k): # প্রতিস্থাপন ছাড়া পরপর তোলা: সংখ্যাগুলোর গুণফল/মোটের অধঃক্রমিক গুণফল
    good,total=k[0],k[1]; r=F(1)
    for i in range(k[2]): r*=F(good-i,total-i)
    return r
isprime=lambda n: n>1 and all(n%d for d in range(2,int(n**.5)+1))
# পাঠ্যবই ১৭
assert P(coin(2,'LC'),lambda w:w.count('L')==1)==F(1,2) and P(coin(2,'LC'),lambda w:'C' not in w)==F(1,4) and len(coin(4,'LC'))==16
# পাঠ্যবই ১৮
assert F(8,25)==F(8,25) and F(15,25)==F(3,5) and nr(10,25,4)==F(21,1265)
# এদের মতো ১০টি
assert P(coin(2),lambda w:'H' in w)==F(3,4) and P(coin(3),lambda w:w.count('H')==2)==F(3,8) and P(coin(3),lambda w:w.count('T')>=2)==F(1,2)
assert F(4,15)==F(4,15) and F(10,15)==F(2,3) and nr(6,15,2)==F(1,7)
cd=list(product('HT',range(1,7))); assert len(cd)==12 and P(cd,lambda w:w[0]=='H' and w[1]%2==0)==F(1,4) and P(cd,lambda w:w[0]=='T' or w[1]==5)==F(7,12)
assert P(coin(4),lambda w:w.count('H')==4)==F(1,16) and P(coin(4),lambda w:w.count('H')==2)==F(3,8) and P(coin(4),lambda w:'T' in w)==F(15,16)
assert F(3,10)==F(3,10) and F(7,10)==F(7,10) and F(2,10)==F(1,5) and nr(5,10,3)==F(1,12)
bw=list(product('RRRRWWWWWW',repeat=2)); assert P(bw,lambda w:w==('W','W'))==F(9,25) and P(bw,lambda w:set(w)=={'R','W'})==F(12,25) and nr(6,10,2)==F(1,3) and F(9,25)>F(1,3)
assert P(coin(3,'LC'),lambda w:w.count('C')==1)==F(3,8) and P(coin(3,'LC'),lambda w:len(set(w))==1)==F(1,4)
cards=range(1,21); assert P(cards,isprime)==F(2,5) and P(cards,lambda n:n%3==0 or n%5==0)==F(9,20) and nr(10,20,2)==F(9,38)
assert P(dice2,lambda w:sum(w)==7)==F(1,6) and P(dice2,lambda w:w[0]==w[1])==F(1,6) and P(dice2,lambda w:sum(w)>=10)==F(1,6) and P(dice2,lambda w:isprime(sum(w)))==F(5,12)
assert F(2,10)==F(1,5) and nr(3,10,2)==F(1,15) and nr(3,10,2)+nr(5,10,2)+nr(2,10,2)==F(14,45) and 1-nr(5,10,2)==F(7,9)
# সহজ ৮
d1=range(1,7); assert P(d1,lambda n:n%2==0)==F(1,2) and P(d1,lambda n:n%2==0 or n%3==0)==F(2,3) and P(d1,lambda n:not isprime(n))==F(1,2) and P(d1,lambda n:n>5)==F(1,6)
assert F(50,600)==F(1,12) and F(190,600)==F(19,60) and F(410,600)==F(41,60) and F(460,600)==F(23,30)
assert F(120,1600)==F(3,40) and F(1320,1600)==F(33,40) and F(400,1600)==F(1,4)
assert 940+30+15+8+4+3==1000 and F(30,1000)==F(3,100) and F(3,1000)==F(3,1000) and F(60,1000)==F(3,50) and F(985,1000)==F(197,200)
a,b=F(4,7),F(2,5); assert 1-a==F(3,7) and a*b==F(8,35) and (1-a)*b==F(6,35) and a*(1-b)==F(12,35)
assert len(coin(2))==4 and P(coin(2),lambda w:'H' in w)==F(3,4) and P(coin(2),lambda w:w[0]==w[1])==F(1,2)
t=range(1,31); assert P(t,lambda n:n%2==0)==F(1,2) and P(t,lambda n:n%4==0)==F(7,30) and P(t,lambda n:n%3==0 or n%5==0)==F(7,15)
assert (4+6)/(1-F(1,3))==15 and F(4,15)==F(4,15) and F(9,15)==F(3,5) and nr(5,15,2)==F(2,21)
# মধ্যম ৮
pl=1-F(2,5)-F(1,3); assert pl==F(4,15) and F(2,5)*F(3,5)==F(6,25) and F(1,3)*F(2,5)==F(2,15) and (1-F(2,5))*F(3,5)==F(9,25)
assert 45+80+50+25==200 and F(45,200)==F(9,40) and F(125,200)==F(5,8) and nr(45,200,2)==F(99,1990)
assert len(dice2)==36 and P(dice2,lambda w:w[0]%2==0 and w[1]%2==0)==F(1,4) and P(dice2,lambda w:w[0]==6 and w[1]!=6)==F(5,36) and P(dice2,lambda w:sum(w)==8)==F(5,36) and P(dice2,lambda w:(w[0]*w[1])%2==0)==F(3,4)
b_,t_=F(3,4),F(2,3); assert (1-b_,1-t_)==(F(1,4),F(1,3)) and b_*(1-t_)==F(1,4) and (1-b_)*t_==F(1,6) and 1-(1-b_)*(1-t_)==F(11,12)
rw=list(product('RRRWW',repeat=2)); assert [P(rw,lambda w,p=p:w==p) for p in [('R','R'),('R','W'),('W','R'),('W','W')]]==[F(9,25),F(6,25),F(6,25),F(4,25)]
assert P(rw,lambda w:w[0]!=w[1])==F(12,25) and P(rw,lambda w:'W' in w)==F(16,25)
assert 120+45+20+10+5==200 and F(45,200)==F(9,40) and F(5,200)==F(1,40) and F(80,200)==F(2,5) and F(185,200)==F(37,40)
assert 2**5==32 and P(coin(5),lambda w:'T' not in w)==F(1,32) and P(coin(5),lambda w:'T' in w)==F(31,32) and P(coin(5),lambda w:w.count('H')==1)==F(5,32)==P(coin(5),lambda w:w.count('H')==4)
pr=F(1,2)*F(3,5)+F(1,2)*F(2,6); assert F(1,2)*F(3,5)==F(3,10) and F(1,2)*F(2,6)==F(1,6) and pr==F(7,15) and 1-pr==F(8,15)

S8='HHHH, HHHT, HHTH, HHTT, HTHH, HTHT, HTTH, HTTT, THHH, THHT, THTH, THTT, TTHH, TTHT, TTTH, TTTT'
